package io.clipbridge.android;
import java.nio.file.*;
import org.json.*;
public final class GroupInterop {
    static void host(Path dir,String mode)throws Exception{
        JSONObject input=new JSONObject(Files.readString(dir.resolve("java-input.json"))),identity=GroupCrypto.identity(GroupCrypto.id(),"Android inviter");JSONObject group=GroupCrypto.create(identity,"Android-created group",input.getJSONObject("connection"));Files.writeString(dir.resolve("cleanup.json"),new JSONObject().put("group",group.getString("id")).put("invitations",new JSONArray()).toString());GroupNetwork.provision(group,input.optString("setup"));GroupNetwork.publish(group,identity);
        JSONObject stale=new JSONObject(group.toString());GroupSession host=GroupSession.invite(group,identity,()->{});Files.writeString(dir.resolve("cleanup.json"),new JSONObject().put("group",group.getString("id")).put("invitations",new JSONArray().put(host.code.substring(0,6))).toString());Files.writeString(dir.resolve("java-start.json"),new JSONObject().put("connection",group.getJSONObject("connection")).put("code",host.code).toString());
        GroupSession guest=null;JSONObject[] received={null};JSONObject otherIdentity=null;
        if(mode.equals("phones")){otherIdentity=GroupCrypto.identity(GroupCrypto.id(),"Second Android");guest=GroupSession.join(group.getJSONObject("connection"),host.code,otherIdentity,g->received[0]=g);}
        long deadline=System.currentTimeMillis()+120000;while(!host.done){host.step();if(guest!=null){guest.step();if(host.ready()&&guest.ready()){if(!host.sas.equals(guest.sas))throw new AssertionError("Android safety numbers differ");if(!host.approved)host.approve();if(!guest.approved)guest.approve();}}else if(host.ready()&&!host.approved){Files.writeString(dir.resolve("java-host-sas.txt"),host.sas);Path sas=dir.resolve("guest-sas.txt");if(Files.exists(sas)){if(!Files.readString(sas).equals(host.sas))throw new AssertionError("Reverse safety numbers differ");host.approve();}}if(System.currentTimeMillis()>deadline)throw new AssertionError("Host timeout");Thread.sleep(100);}
        JSONObject member,config;if(guest!=null){member=otherIdentity.getJSONObject("member");config=GroupCrypto.channel(received[0],otherIdentity,identity.getJSONObject("member"));}else{Path resultPath=dir.resolve("guest-result.json");while(!Files.exists(resultPath)){if(System.currentTimeMillis()>deadline)throw new AssertionError("Missing guest result");Thread.sleep(50);}JSONObject result=new JSONObject(Files.readString(resultPath));member=result.getJSONObject("member");config=result.getJSONObject("config");}
        if(!GroupCrypto.channel(group,identity,member).getString("key").equals(config.getString("key")))throw new AssertionError("Host pair key differs");GroupNetwork.publish(stale,identity);if(GroupNetwork.read(group,identity.getJSONObject("member").getString("id")).getLong("sequence")!=group.getLong("sequence"))throw new AssertionError("Stale Java publication rolled membership back");host.close();if(guest!=null)guest.close();System.out.println("PASS Android creates group and invites "+mode+" with matching independent pair keys");
    }
    public static void main(String[] args)throws Exception{
        Path dir=Path.of(args[0]);if(args.length>1){host(dir,args[1]);return;}Path start=dir.resolve("interop-start.json");long deadline=System.currentTimeMillis()+120000;while(!Files.exists(start)){if(System.currentTimeMillis()>deadline)throw new AssertionError("No host invitation");Thread.sleep(100);}
        JSONObject invite=new JSONObject(Files.readString(start)),identity=GroupCrypto.identity(GroupCrypto.id(),"Android Java 中文");
        GroupSession join=GroupSession.join(invite.getJSONObject("connection"),invite.getString("code"),identity,group->{GroupCrypto.validate(group);JSONObject other=group.getJSONObject("members").getJSONObject(invite.getString("hostId")).getJSONObject("member");Files.writeString(dir.resolve("interop-result.json"),new JSONObject().put("member",identity.getJSONObject("member")).put("config",GroupCrypto.channel(group,identity,other)).toString());});
        while(!join.done){join.step();if(join.ready()&&!join.approved){Path sas=dir.resolve("host-sas.txt");if(Files.exists(sas)){if(!Files.readString(sas).equals(join.sas))throw new AssertionError("Cross-platform safety numbers differ");Files.writeString(dir.resolve("java-sas.txt"),join.sas);join.approve();}}if(System.currentTimeMillis()>deadline)throw new AssertionError("Pairing timeout");Thread.sleep(150);}
        System.out.println("PASS Android Java joins .NET group with mutual PAKE and matching safety numbers");
    }
}
